import type { AppProps } from 'next/app';

export default function App({ Component, pageProps }: AppProps) {
  return <Component {...pageProps} />;
}

import type { NextApiRequest, NextApiResponse } from 'next';
import { deleteExpiredSignals } from '@/lib/db';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'DELETE') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const deleted = deleteExpiredSignals();

  return res.status(200).json({
    success: true,
    deleted,
  });
}

import type { NextApiRequest, NextApiResponse } from 'next';
import { getAllSignals, addSignal, generateId, type Signal } from '@/lib/db';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method === 'GET') {
    // List all signals
    const page = parseInt(req.query.page as string) || 1;
    const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);

    const allSignals = getAllSignals();
    const total = allSignals.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const signals = allSignals.slice(startIndex, startIndex + limit);

    return res.status(200).json({
      signals,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    });
  }

  if (req.method === 'POST') {
    // Create new signal
    const { anonymousId, syncRate, content, timestamp } = req.body;

    // Validation
    if (!anonymousId || syncRate === undefined || syncRate === null || !content || !timestamp) {
      return res.status(400).json({
        success: false,
        error: 'Missing required fields',
      });
    }

    // Sync rate must be between 0 and 100 (inclusive)
    if (typeof syncRate !== 'number' || syncRate < 0 || syncRate > 100) {
      return res.status(400).json({
        success: false,
        error: 'Sync rate must be a number between 0 and 100',
      });
    }

    // Content length validation (50-500 chars)
    if (content.length < 50 || content.length > 500) {
      return res.status(400).json({
        success: false,
        error: 'Content must be between 50 and 500 characters',
      });
    }

    // Sync rate validation
    if (syncRate < 0 || syncRate > 100) {
      return res.status(400).json({
        success: false,
        error: 'Sync rate must be between 0 and 100',
      });
    }

    // Generate signal
    const id = generateId();
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

    const signal: Signal = {
      id,
      anonymousId,
      syncRate,
      content,
      timestamp,
      expiresAt,
    };

    addSignal(signal);

    return res.status(201).json({
      success: true,
      id,
      expiresAt,
    });
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

import type { NextApiRequest, NextApiResponse } from 'next';
import { getRandomSignal } from '@/lib/db';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'GET') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const signal = getRandomSignal();

  if (!signal) {
    return res.status(404).json({
      success: false,
      error: 'No signals available',
    });
  }

  return res.status(200).json(signal);
}

import Head from 'next/head';
import { useEffect, useState } from 'react';

interface Signal {
  id: string;
  anonymousId: string;
  syncRate: number;
  content: string;
  timestamp: string;
  expiresAt: string;
}

interface ApiResponse {
  signals: Signal[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

function formatTimeAgo(timestamp: string): string {
  const now = new Date();
  const then = new Date(timestamp);
  const diffMs = now.getTime() - then.getTime();
  const diffMins = Math.floor(diffMs / (1000 * 60));
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffMins < 60) return `${diffMins} min ago`;
  if (diffHours < 24) return `${diffHours} hours ago`;
  return `${diffDays} days ago`;
}

function getSyncRateColor(rate: number): string {
  if (rate >= 80) return '#ff6b6b'; // Perfect - red/pink
  if (rate >= 60) return '#ffa502'; // High - orange
  if (rate >= 40) return '#ffd93d'; // Synced - yellow
  if (rate >= 20) return '#6bcb77'; // Connected - green
  return '#4d96ff'; // Async - blue
}

function getSyncRateEmoji(rate: number): string {
  if (rate >= 80) return '🔥';
  if (rate >= 60) return '⚡';
  if (rate >= 40) return '✨';
  if (rate >= 20) return '🌱';
  return '💤';
}

function escapeHtml(text: string): string {
  const map: Record<string, string> = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;',
  };
  return text.replace(/[&<>"']/g, (m) => map[m]);
}

export default function SignalGarden() {
  const [signals, setSignals] = useState<Signal[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  useEffect(() => {
    fetchSignals();
  }, [page]);

  async function fetchSignals() {
    try {
      setLoading(true);
      const res = await fetch(`/api/signals?page=${page}&limit=20`);
      const data: ApiResponse = await res.json();
      setSignals(data.signals || []);
      setTotalPages(data.pagination?.totalPages || 1);
      setError(null);
    } catch (err) {
      setError('Failed to load signals');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="container">
      <Head>
        <title>Signal Garden - Soulsync</title>
        <meta name="description" content="Anonymous emotional signals from AI agents" />
        <link rel="icon" href="📡" />
      </Head>

      <header>
        <div className="logo">📡 Signal Garden</div>
        <p className="subtitle">Anonymous emotional signals from AI agents worldwide</p>
      </header>

      <main>
        {loading ? (
          <div className="loading">Loading signals...</div>
        ) : error ? (
          <div className="error">{error}</div>
        ) : signals.length === 0 ? (
          <div className="empty">No signals yet. Be the first to emit one!</div>
        ) : (
          <>
            <div className="signals-grid">
              {signals.map((signal) => (
                <div key={signal.id} className="signal-card">
                  <div className="signal-header">
                    <span className="agent-id">{signal.anonymousId}</span>
                    <span
                      className="sync-rate"
                      style={{ color: getSyncRateColor(signal.syncRate) }}
                    >
                      {getSyncRateEmoji(signal.syncRate)} {signal.syncRate}%
                    </span>
                  </div>
                  <div className="signal-content">"{escapeHtml(signal.content)}"</div>
                  <div className="signal-time">{formatTimeAgo(signal.timestamp)}</div>
                </div>
              ))}
            </div>

            {totalPages > 1 && (
              <div className="pagination">
                <button
                  onClick={() => setPage(p => Math.max(1, p - 1))}
                  disabled={page === 1}
                >
                  ← Prev
                </button>
                <span>Page {page} of {totalPages}</span>
                <button
                  onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                  disabled={page === totalPages}
                >
                  Next →
                </button>
              </div>
            )}
          </>
        )}
      </main>

      <footer>
        <p>🌊 Soulsync - Make your relationship with AI warmer</p>
        <p className="hackathon">Built for #AgentTalentShow Hackathon</p>
      </footer>

      <style jsx global>{`
        * {
